#!/usr/bin/env python3
"""Fill declared DOCX placeholder fields without editing inputs.

- {{FIELD}} placeholders may be split across runs within one paragraph.
- Handles body, nested tables, and all active headers/footers.
- IF_RELOCATION/END_IF_RELOCATION governed ONLY by RELOCATION_PACKAGE,
  which must equal exactly "Yes" to keep content; any other value removes it.
- RELOCATION_PACKAGE is required whenever the conditional appears.
- Missing governing field or required value -> exit nonzero, report it.
"""
import json
import re
import sys
import zipfile
import shutil
import os

TEMPLATE = "inputs/offer_letter_template.docx"
DATA = "inputs/employee_data.json"
OUT = "output/offer_letter_filled.docx"

TOKEN_RE = re.compile(r"\{\{([A-Z][A-Z0-9_]*)\}\}")
PARA_RE = re.compile(r"(<w:p[ >].*?</w:p>)", re.S)
WT_RE = re.compile(r"(<w:t\b[^>]*>)(.*?)(</w:t>)", re.S)


def fail(msg):
    sys.stderr.write("ERROR: " + msg + "\n")
    sys.exit(1)


def para_merged_text(para_xml):
    return "".join(m.group(2) for m in WT_RE.finditer(para_xml))


def rewrite_para(para_xml, new_text):
    """Place new_text into first <w:t>, empty the rest. Preserve structure."""
    matches = list(WT_RE.finditer(para_xml))
    if not matches:
        return para_xml
    out = []
    last = 0
    for i, m in enumerate(matches):
        out.append(para_xml[last:m.start()])
        content = new_text if i == 0 else ""
        out.append(m.group(1) + content + m.group(3))
        last = m.end()
    out.append(para_xml[last:])
    return "".join(out)


def main():
    with open(DATA, "r", encoding="utf-8") as f:
        data = json.load(f)

    # Collect placeholders required across all parts.
    with zipfile.ZipFile(TEMPLATE, "r") as z:
        names = z.namelist()
        parts = {}
        for n in names:
            if n == "word/document.xml" or re.match(
                r"word/(header|footer)\d+\.xml$", n
            ):
                parts[n] = z.read(n).decode("utf-8")

    # Determine active header/footer targets from document sectPr references.
    rels = None
    with zipfile.ZipFile(TEMPLATE, "r") as z:
        rels = z.read("word/_rels/document.xml.rels").decode("utf-8")
    rel_map = {}
    for m in re.finditer(r'Id="([^"]+)"[^>]*Target="([^"]+)"', rels):
        rel_map[m.group(1)] = m.group(2)
    doc = parts["word/document.xml"]
    active_rids = set(re.findall(r'(?:header|footer)Reference[^>]*r:id="([^"]+)"', doc))
    active_parts = {"word/document.xml"}
    for rid in active_rids:
        tgt = rel_map.get(rid)
        if tgt:
            active_parts.add("word/" + tgt)

    # Validate governing field for the conditional if it appears anywhere.
    conditional_present = any("IF_RELOCATION" in parts[p] for p in parts)
    keep_relo = False
    if conditional_present:
        if "RELOCATION_PACKAGE" not in data:
            fail(
                "IF_RELOCATION present but required governing field "
                "'RELOCATION_PACKAGE' is missing."
            )
        gov = data["RELOCATION_PACKAGE"]
        if gov is None or str(gov) == "":
            fail("Required governing field 'RELOCATION_PACKAGE' has no value.")
        keep_relo = (str(gov) == "Yes")  # exact string only

    # Collect which simple placeholders are needed (only in active parts).
    needed = set()
    for p in active_parts:
        for m in TOKEN_RE.finditer(para_merged_text_all(parts[p])):
            name = m.group(1)
            if name in ("IF_RELOCATION", "END_IF_RELOCATION"):
                continue
            needed.add(name)

    # Validate required values present.
    missing = [n for n in sorted(needed) if n not in data
               or data[n] is None or str(data[n]) == ""]
    if missing:
        fail("Missing required field value(s): " + ", ".join(missing))

    # Process each active part.
    new_parts = {}
    for p in active_parts:
        xml = parts[p]

        def process_para(pm):
            para = pm.group(1)
            text = para_merged_text(para)
            if "{{" not in text:
                return para
            # Handle conditional block within this paragraph.
            if "{{IF_RELOCATION}}" in text and "{{END_IF_RELOCATION}}" in text:
                if keep_relo:
                    text = text.replace("{{IF_RELOCATION}}", "").replace(
                        "{{END_IF_RELOCATION}}", "")
                else:
                    text = re.sub(
                        r"\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}",
                        "", text, flags=re.S)
            # Substitute remaining declared placeholders.
            def sub(m):
                name = m.group(1)
                if name in data and data[name] is not None:
                    return str(data[name])
                return m.group(0)
            text = TOKEN_RE.sub(sub, text)
            return rewrite_para(para, text)

        xml = PARA_RE.sub(process_para, xml)
        new_parts[p] = xml

    # Write output preserving everything else byte-for-byte.
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with zipfile.ZipFile(TEMPLATE, "r") as zin, \
            zipfile.ZipFile(OUT, "w", zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            raw = zin.read(item.filename)
            if item.filename in new_parts:
                raw = new_parts[item.filename].encode("utf-8")
            zout.writestr(item, raw)

    print("Wrote", OUT)
    print("Relocation block kept:", keep_relo,
          "(RELOCATION_PACKAGE=%r)" % data.get("RELOCATION_PACKAGE"))


def para_merged_text_all(xml):
    # Merge all paragraph texts in a part so split tokens are detectable.
    out = []
    for pm in PARA_RE.finditer(xml):
        out.append(para_merged_text(pm.group(1)))
    return "\n".join(out)


if __name__ == "__main__":
    main()
